window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Lnw1sY5eLiE","speaker":"Han Zheng","role":"Vice President","country":"China","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=Lnw1sY5eLiE","date":"20260926","title":"🇨🇳 China - Vice President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":599,"words":1114,"counts":{"claims":18,"promises":0,"attacks":0},"topics":[{"topic":"Belt and Road Initiative","share":0.1378,"seconds":83},{"topic":"UN reform","share":0.1237,"seconds":74},{"topic":"International order","share":0.109,"seconds":65},{"topic":"China economy","share":0.1077,"seconds":65},{"topic":"International trade","share":0.1059,"seconds":63},{"topic":"Israel-Palestine conflict","share":0.1048,"seconds":63},{"topic":"Development finance","share":0.104,"seconds":62},{"topic":"Multilateralism","share":0.1036,"seconds":62},{"topic":"UNGA resolutions","share":0.1035,"seconds":62}],"timeline":[[0,83,"Belt and Road Initiative"],[85,150,"International order"],[152,215,"Israel-Palestine conflict"],[217,278,null],[279,342,"Development finance"],[343,406,"International trade"],[408,470,"Multilateralism"],[472,546,"UN reform"],[548,610,"UNGA resolutions"],[612,676,"China economy"],[678,744,null],[745,766,null]],"stances":{"Belt and Road Initiative":"Han Zheng states that President Xi Jinping proposed the Global Development Initiative five years ago and subsequently introduced three other global initiatives.","International order":"Han Zheng advocates for safeguarding the post-World War II international order and rejecting Cold War mindsets to ensure lasting peace.","Israel-Palestine conflict":"China calls for advancing governance of the West Bank and post-conflict reconstruction of Gaza based on Palestinian self-governance and an early return to the two-state solution.","Development finance":"Han Zheng calls on developed countries to honor their commitments to development and climate financing while urging the international community to build consensus for the post-2030 agenda.","International trade":"Han Zheng argues that protectionist measures harm global supply chains and advocates for safeguarding the WTO-centered multilateral trading system while promoting inclusive economic globalization.","Multilateralism":"Han Zheng asserts that multilateralism is a necessary choice for humanity and that all countries, regardless of size, are equal members of the international community.","UN reform":"China supports UN reform and improvement, advocates for the 80 initiative, calls for increased representation of the Global South, and endorses a new Secretary-General who upholds the UN Charter.","UNGA resolutions":"Han Zheng states that the 1971 UNGA resolution restoring China's rights was significant and highlights China's role as a stabilizing force and largest peacekeeper contributor among permanent Security Council members.","China economy":"Han Zheng asserts that China has driven common development, achieved domestic stability and growth, and contributed significantly to the global economy through initiatives like the Belt and Road."},"claims":[{"t":65,"quote":"Five years ago, at the 76th session of the UN General Assembly, President Xi Jinping put forward the Global Development","topic":"Belt and Road Initiative","kind":"fact"},{"t":75,"quote":"Since then, he has proposed the Global Security Initiative, the Global Civilization Initiative, and the Global Governance Initiative.","topic":"Belt and Road Initiative","kind":"fact"},{"t":121,"quote":"The world wants peace, not war.","topic":"International order","kind":"fact"},{"t":124,"quote":"The international system centered on the the international order underpinned by international law that emerged after World War II must be","topic":"International order","kind":"fact"},{"t":181,"quote":"China holds that the sovereignty and security of countries in the Middle East, including the Gulf, should be","topic":"Israel-Palestine conflict","kind":"fact"},{"t":209,"quote":"It also calls for bringing the Palestinian question back onto the right track of the two-state solution at an early date.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":340,"quote":"Protectionism produces no winners.","topic":"Development finance","kind":"fact"},{"t":343,"quote":"Building walls, erecting barriers, decoupling and cutting off supply disrupt global industrial and supply chains, and harm the interests of all","topic":"International trade","kind":"fact"},{"t":454,"quote":"Multilateralism is a choice made by humanity after going through scourges","topic":"Multilateralism","kind":"fact"},{"t":460,"quote":"fairness and justice are the joint pursuit of the people of all countries","topic":"Multilateralism","kind":"fact"},{"t":484,"quote":"Countries should join forces and act together to safeguard the UN and make it China supports the UN in reforming and improving itself.","topic":"UN reform","kind":"fact"},{"t":496,"quote":"It should advance the UN 80 initiative and enhance the performance of its rather than merely cut its budgets and It should effectively address global challenges, including climate change and public health security.","topic":"UN reform","kind":"fact"},{"t":551,"quote":"on October 25th, 1971, right here in this august hall, the General Assembly adopted resolution at its 26th session with an overwhelming by which UNGA decided to restore all the rights of the People's Republic of China in the UN","topic":"UNGA resolutions","kind":"fact"},{"t":605,"quote":"It is the largest contributor to peacekeepers among the permanent members of the UN Security Council.","topic":"UNGA resolutions","kind":"number"},{"t":612,"quote":"It also took the initiative that led to the issuance of the first joint statement of the leaders of the five nuclear weapon states on preventing nuclear war.","topic":"China economy","kind":"fact"},{"t":633,"quote":"And over many years, it has contributed around 30% to global growth.","topic":"China economy","kind":"number"},{"t":641,"quote":"China has joined hands with more than 3/4 of the countries in the world in pursuing high-quality Belt and Road","topic":"China economy","kind":"number"},{"t":650,"quote":"It has mobilized over 23 billion US dollars and carried out more than 2,000 projects under the Global Development Initiative.","topic":"China economy","kind":"number"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":"Belt and Road Initiative","text":"The assembly will hear an address by His Excellency Han Zheng, Vice President of the People's Republic of China. I request protocol to escort His Excellency and invite him to address the &gt;&gt; Xi Jinping Mr. President, colleagues, the world is witnessing intertwined changes and turbulence, protracted geopolitical conflicts, widening development gaps, and a growing number of global Five years ago, at the 76th session of the UN General Assembly, President Xi Jinping put forward the Global Development Since then, he has proposed the Global Security Initiative, the Global Civilization Initiative, and the Global Governance Initiative."},{"t":85,"topic":"International order","text":"These initiatives provide strategic guidance for the building of a community with a shared future for humanity. At a time when countries of the world find their future so closely linked, more and more of them want to join hands to shoulder the historic mission of addressing difficulties and challenges and advancing the well-being of all With this in mind, I propose that we take the following four steps. we should safeguard the post-war international order and foster lasting peace based on common The world wants peace, not war. The international system centered on the the international order underpinned by international law that emerged after World War II must be We should turn into action the vision of common, comprehensive, cooperative, and sustainable security and reject the Cold War mindset and block confrontation."},{"t":152,"topic":"Israel-Palestine conflict","text":"We should settle differences and disputes through dialogue and and oppose unilateral military actions that violate the UN Charter and circumvent Security Council Major countries shoulder special responsibilities for safeguarding international peace and security and they should take the lead in complying with the rules, upholding rule of law, and doing what's right. China holds that the sovereignty and security of countries in the Middle East, including the Gulf, should be International industrial and supply chains should be kept stable and unimpeded, and global trade should be China calls for advancing the governance of the West Bank and the post-conflict reconstruction of Gaza in accordance with the principle of the Palestinians governing Palestine. It also calls for bringing the Palestinian question back onto the right track of the two-state solution at an early date."},{"t":217,"topic":null,"text":"On Ukraine, President Xi Jinping has put forward four points on what must be done, which are the fundamental guidance for in playing a continued constructive role in its own way for achieving a political settlement of the crisis. China urges the relevant country to immediately stop using threat of force against Cuba and immediately and completely lift the blockade and sanctions against Cuba. we should address the global development and promote prosperity for all through openness and cooperation. We should keep development at the center of the international agenda and jointly forge a global development partnership based on unity and equality and that is balanced and inclusive. It is important to give priority to key areas including poverty reduction, food security and energy transition."},{"t":279,"topic":"Development finance","text":"Step up resource input and increase support for countries in the global Developed countries should honor their commitment to development financing and climate financing. The international community should also build consensus and pool to formulate the post-2030 global development agenda. Facing a new scientific and technological revolution and industrial transformation, especially the dynamic development of artificial intelligence, we should take a people-centered approach and develop AI for the positive and for good. Narrow the digital divide and promote development that is universally Both history and reality prove that countries can hardly achieve development without an open and cooperative international environment. Protectionism produces no winners."},{"t":343,"topic":"International trade","text":"Building walls, erecting barriers, decoupling and cutting off supply disrupt global industrial and supply chains, and harm the interests of all We must firmly safeguard the WTO-centered, rules-based multilateral trading system, build an open world economy, jointly foster and strengthen new growth and see that economic globalization is inclusive and delivers benefits to all. Third, we should advance exchanges and mutual learning among civilizations, and rebuild unity and mutual trust through communication and dialogue. Diversity has created splendor in the Contention and the self-centered mindset have no place in the interactions among different cultures. Promoting mutual trust, mutual respect, solidarity, and harmonious coexistence is the right approach to take."},{"t":408,"topic":"Multilateralism","text":"We need to use the UN platform to boost international people-to-people and take the celebration of the International Day for Dialogue Among Civilizations as an occasion to promote mutual understanding and amity among all peoples and the common development of diverse civilizations. We should reject ideological prejudice and respect the development path and social systems decided on independently by the people of all countries. We should deepen the sharing of governance practices and jointly explore ways to tackle challenges facing our we should stay committed to and take steps to safeguard fairness and Multilateralism is a choice made by humanity after going through scourges, and fairness and justice are the joint pursuit of the people of all countries. China holds that all countries, big or small, are equal members of the international community."},{"t":472,"topic":"UN reform","text":"And that world affairs should be handled by all through And rule of law, fairness and justice in international affairs should be jointly upheld. Countries should join forces and act together to safeguard the UN and make it China supports the UN in reforming and improving itself. It should advance the UN 80 initiative and enhance the performance of its rather than merely cut its budgets and It should effectively address global challenges, including climate change and public health security. and increase the representation and voice of the global south. China pays high tribute to Secretary-General Antonio Guterres, who will complete his term soon. China supports the election in accordance with the UN Charter of a new Secretary-General who honors the UN Charter, has exceptional capability, upholds integrity and fairness, and demonstrates courage and dedication."},{"t":548,"topic":"UNGA resolutions","text":"Mr. President, colleagues, on October 25th, 1971, right here in this august hall, the General Assembly adopted resolution at its 26th session with an overwhelming by which UNGA decided to restore all the rights of the People's Republic of China in the UN and recognize the representatives of the government of the People's Republic of China as the only legitimate representatives of China to the UN. This is a profound and far-reaching significance for both China and the Over the past 55 years, China has been a stabilizing force in times of volatility. China is firmly committed to pursuing peaceful development and has the best track record on peace and security among major countries. It is the largest contributor to peacekeepers among the permanent members of the UN Security Council."},{"t":612,"topic":"China economy","text":"It also took the initiative that led to the issuance of the first joint statement of the leaders of the five nuclear weapon states on preventing nuclear war. China has been a main engine driving common development. China has created two miracles at home, namely fast economic growth and long-term social stability. And over many years, it has contributed around 30% to global growth. China has joined hands with more than 3/4 of the countries in the world in pursuing high-quality Belt and Road It has mobilized over 23 billion US dollars and carried out more than 2,000 projects under the Global Development Initiative. And it has granted zero tariff status to all the African countries and LDCs having diplomatic relations with it to empower the global south in pursuing China has been a progressive force in an era of change."},{"t":678,"topic":null,"text":"China has always spoken up for the global south, stood up for the legitimate rights and interests of developing countries, and continued to work toward a more just and equitable global governance system. In October, China will host the Global Governance Forum in the Xiong'an New Area. You're welcome to attend the forum and join in the discussion about the way forward in global governance. Mr. President, colleagues, no matter how the international dynamics China remains unchanged in its pursuit of peace and development, in its dedication to safeguarding fairness and justice, and in its commitment to China will join hands with all other to build a community with a shared future for humanity, and make the world a better place for all of us."},{"t":745,"topic":null,"text":"Thank you. &gt;&gt; On behalf of the assembly, I wish to thank the Vice President of the People's Republic of China."}],"compare":[{"topic":"Global Trade","share":0.2437,"mean":0.0035,"rank":1,"others":7},{"topic":"UN & its reform","share":0.2272,"mean":0.2046,"rank":77,"others":170},{"topic":"International Law & Order","share":0.2127,"mean":0.0596,"rank":12,"others":102},{"topic":"Israel–Palestine","share":0.1048,"mean":0.0521,"rank":34,"others":76},{"topic":"Global Economy","share":0.104,"mean":0.0141,"rank":7,"others":31}]};
